export type Grant = {
  id: string;
  title: string;
  organization: string;
  category: string;
  amountMin: number;
  amountMax: number;
  applicationStart: string; // ISO date
  applicationEnd: string;
  target: string;
  description: string;
  url?: string;
  region?: string;
  custom?: boolean;
};

export const CATEGORIES = [
  "子ども・教育",
  "環境・自然",
  "福祉・医療",
  "地域振興",
  "災害支援",
  "文化・芸術",
  "国際協力",
] as const;

export const REGIONS = [
  "全国",
  "北海道",
  "東北",
  "関東",
  "東京",
  "中部",
  "東海",
  "関西",
  "中国",
  "四国",
  "九州",
  "沖縄",
] as const;

export const getGrantRegion = (g: Grant): string => {
  if (g.region) return g.region;
  const src = `${g.organization} ${g.target}`;
  for (const r of REGIONS) {
    if (r !== "全国" && src.includes(r)) return r;
  }
  return "全国";
};

